1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9		"strconv"
10		"unicode/utf8"
11	)
12	
13	// EvalReason is the machine-readable outcome of a flag evaluation.
14	type EvalReason string
15	
16	const (
17		EvalDisabled EvalReason = "disabled"
18		EvalRule     EvalReason = "rule"
19		EvalDefault  EvalReason = "default"
20	)
21	
22	// Condition is one predicate over an evaluation context.
23	type Condition struct {
24		Attribute string
25		Op        string
26		// strVal 用于 eq；inVal 用于 in（至少一项）。
27		strVal string
28		inVal  []string
29	}
30	
31	// Rule groups conditions that must all hold; on match the flag takes Value.
32	type Rule struct {
33		ID         string
34		Value      bool
35		Conditions []Condition
36	}
37	
38	// Flag is one feature toggle with its default and ordered rules.
39	type Flag struct {
40		Key     string
41		Enabled bool
42		Default bool
43		Rules   []Rule
44	}
45	
46	// Config is a validated feature flag configuration.
47	type Config struct {
48		Flags []Flag
49	}
50	
51	// EvalResult is the deterministic outcome of evaluating one flag.
52	type EvalResult struct {
53		Key    string     `json:"key"`
54		Value  bool       `json:"value"`
55		Reason EvalReason `json:"reason"`
56		RuleID *string    `json:"ruleId"`
57	}
58	
59	// Equals reports whether two evaluation results are identical.
60	func (r EvalResult) Equals(other EvalResult) bool {
61		if r.Key != other.Key || r.Value != other.Value || r.Reason != other.Reason {
62			return false
63		}
64		if (r.RuleID == nil) != (other.RuleID == nil) {
65			return false
66		}
67		if r.RuleID != nil && *r.RuleID != *other.RuleID {
68			return false
69		}
70		return true
71	}
72	
73	// Context is a validated map of attribute names to string values.
74	type Context struct {
75		values map[string]string
76	}
77	
78	// LoadConfig reads and strictly validates a UTF-8 JSON flag config file.
79	// 所有开关都会被完整校验，包括不会被求值或已关闭的开关。
80	func LoadConfig(path string) (*Config, error) {
81		raw, err := os.ReadFile(path)
82		if err != nil {
83			return nil, fmt.Errorf("cannot read config file %q: %w", path, err)
84		}
85		return ParseConfig(raw)
86	}
87	
88	// LoadContext reads and validates a UTF-8 JSON context file.
89	func LoadContext(path string) (*Context, error) {
90		raw, err := os.ReadFile(path)
91		if err != nil {
92			return nil, fmt.Errorf("cannot read context file %q: %w", path, err)
93		}
94		return ParseContext(raw)
95	}
96	
97	// unmarshalStrictJSON 严格解码一个 UTF-8 JSON 文档到 any，并保持与
98	// json.Unmarshal 相同的单文档语义：文档之后只允许空白，不允许第二个值。
99	// 使用 json.Decoder + UseNumber：数字按原文保留为 json.Number，而不是强制
100	// 转成 float64——语法合法但超出浮点范围的数字（如 1e400、由 1 后接 400 个 0
101	// 组成的整数）不应被当成“JSON 无效”，它们是合法的 JSON 数字，由后续的值
102	// 类型检查以所属字段的类型错误报告。
103	func unmarshalStrictJSON(raw []byte) (any, error) {
104		dec := json.NewDecoder(bytes.NewReader(raw))
105		dec.UseNumber()
106		var doc any
107		if err := dec.Decode(&doc); err != nil {
108			return nil, err
109		}
110		// Decoder 本身容忍文档之后的额外 JSON 值，需显式补回 Unmarshal 的严格性。
111		offset := int(dec.InputOffset())
112		var extra any
113		if err := dec.Decode(&extra); err != io.EOF {
114			if err != nil {
115				return nil, err
116			}
117			for offset < len(raw) && isJSONWhitespace(raw[offset]) {
118				offset++
119			}
120			c := byte(0)
121			if offset < len(raw) {
122				c = raw[offset]
123			}
124			return nil, fmt.Errorf("invalid character %q after top-level value", c)
125		}
126		return doc, nil
127	}
128	
129	// isJSONWhitespace 报告 b 是否为 JSON 允许的空白字节。
130	func isJSONWhitespace(b byte) bool {
131		return b == ' ' || b == '\t' || b == '\n' || b == '\r'
132	}
133	
134	// ParseConfig parses a config document from JSON bytes with strict typing.
135	// 先解析到 any 再逐字段校验，以区分“字段缺失”与“显式提供的 false”。
136	func ParseConfig(raw []byte) (*Config, error) {
137		if !utf8.Valid(raw) {
138			return nil, fmt.Errorf("config: file is not valid UTF-8")
139		}
140		if err := rejectInvalidUnicodeEscapes(raw, "config"); err != nil {
141			return nil, err
142		}
143		if err := rejectDuplicateFields(raw, "config"); err != nil {
144			return nil, err
145		}
146		doc, err := unmarshalStrictJSON(raw)
147		if err != nil {
148			return nil, fmt.Errorf("config: invalid JSON: %w", err)
149		}
150		root, ok := doc.(map[string]any)
151		if !ok {
152			return nil, fmt.Errorf("config: top level must be a JSON object")
153		}
154		flagsRaw, present := root["flags"]
155		if !present {
156			return nil, fmt.Errorf("config.flags: field is required")
157		}
158		if flagsRaw == nil {
159			return nil, fmt.Errorf("config.flags: must be an array, got null")
160		}
161		flagsArr, ok := flagsRaw.([]any)
162		if !ok {
163			return nil, fmt.Errorf("config.flags: must be an array")
164		}
165		cfg := &Config{}
166		seenKeys := map[string]int{}
167		for i, fr := range flagsArr {
168			flag, err := parseFlag(fr, i)
169			if err != nil {
170				return nil, err
171			}
172			if prev, dup := seenKeys[flag.Key]; dup {
173				return nil, fmt.Errorf("config.flags[%d].key: duplicate flag key %q (first at flags[%d])", i, flag.Key, prev)
174			}
175			seenKeys[flag.Key] = i
176			cfg.Flags = append(cfg.Flags, flag)
177		}
178		return cfg, nil
179	}
180	
181	// ParseContext parses an attribute-name -> string context object; it may be empty.
182	func ParseContext(raw []byte) (*Context, error) {
183		if !utf8.Valid(raw) {
184			return nil, fmt.Errorf("context: file is not valid UTF-8")
185		}
186		if err := rejectInvalidUnicodeEscapes(raw, "context"); err != nil {
187			return nil, err
188		}
189		if err := rejectDuplicateFields(raw, "context"); err != nil {
190			return nil, err
191		}
192		doc, err := unmarshalStrictJSON(raw)
193		if err != nil {
194			return nil, fmt.Errorf("context: invalid JSON: %w", err)
195		}
196		root, ok := doc.(map[string]any)
197		if !ok {
198			return nil, fmt.Errorf("context: top level must be a JSON object")
199		}
200		// 语法校验通过后才建立可用属性：值类型检查与属性建立在同一次遍历中完成。
201		return buildContext(raw, root)
202	}
203	
204	// buildContext 按文件原文顺序做一次流式遍历，同时完成顶层属性的值类型检查
205	// 与可用属性的建立：字段名顺序取自令牌流（Go map 的遍历顺序不稳定，不能
206	// 直接 range root，否则同一文件在不同运行中可能报告不同属性），属性值复用
207	// 严格解码得出的 root——同一份上下文的值只解码一次。语法、重复字段与 Unicode
208	// 转义已在此前校验，这里的令牌读取不会再遇到错误。键名使用解码后的文字
209	// （合法的 \uXXXX 转义与直接字符同义；大小写与空白按原样保留）。对象或数组
210	// 值整体算所属顶层属性的一个值，错误不指向其内部成员。
211	func buildContext(raw []byte, root map[string]any) (*Context, error) {
212		dec := json.NewDecoder(bytes.NewReader(raw))
213		// 消费顶层对象的 '{'；语法已由 unmarshalStrictJSON 校验。
214		if _, err := dec.Token(); err != nil {
215			return nil, fmt.Errorf("context: invalid JSON: %w", err)
216		}
217		ctx := &Context{values: make(map[string]string, len(root))}
218		for dec.More() {
219			keyTok, err := dec.Token()
220			if err != nil {
221				return nil, fmt.Errorf("context: invalid JSON: %w", err)
222			}
223			key, _ := keyTok.(string)
224			// 值不再重复解码：RawMessage 只把读取位置推进到下一个字段，
225			// 实际值取自已严格解码的 root。数字（含超出浮点范围的 json.Number）、
226			// 布尔、null、对象、数组都在这里按所属属性报类型错误。
227			var skipped json.RawMessage
228			if err := dec.Decode(&skipped); err != nil {
229				return nil, fmt.Errorf("context: invalid JSON: %w", err)
230			}
231			s, ok := root[key].(string)
232			if !ok {
233				return nil, fmt.Errorf("%s: value must be a string", appendFieldPath("context", key))
234			}
235			ctx.values[key] = s
236		}
237		return ctx, nil
238	}
239	
240	// Get looks up an attribute; an empty string is a legal value.
241	func (c *Context) Get(attribute string) (string, bool) {
242		if c == nil {
243			return "", false
244		}
245		v, ok := c.values[attribute]
246		return v, ok
247	}
248	
249	// Find returns the flag with the given key, or nil if absent.
250	func (c *Config) Find(key string) *Flag {
251		if c == nil {
252			return nil
253		}
254		for i := range c.Flags {
255			if c.Flags[i].Key == key {
256				return &c.Flags[i]
257			}
258		}
259		return nil
260	}
261	
262	// Evaluate deterministically evaluates a flag against a context.
263	// 未启用固定 false（reason=disabled），不使用默认值或规则；启用后取首条
264	// 所有条件均成立的规则的 value；无匹配取 default。求值不依赖时间、随机数
265	// 或 map 遍历顺序，同一配置与上下文重复求值结果一致。
266	func (f *Flag) Evaluate(ctx *Context) EvalResult {
267		if !f.Enabled {
268			return EvalResult{Key: f.Key, Value: false, Reason: EvalDisabled, RuleID: nil}
269		}
270		for i := range f.Rules {
271			rule := &f.Rules[i]
272			if rule.matches(ctx) {
273				id := rule.ID
274				return EvalResult{Key: f.Key, Value: rule.Value, Reason: EvalRule, RuleID: &id}
275			}
276		}
277		return EvalResult{Key: f.Key, Value: f.Default, Reason: EvalDefault, RuleID: nil}
278	}
279	
280	func (r *Rule) matches(ctx *Context) bool {
281		for i := range r.Conditions {
282			if !r.Conditions[i].matches(ctx) {
283				return false
284			}
285		}
286		return true
287	}
288	
289	func (c Condition) matches(ctx *Context) bool {
290		v, present := ctx.Get(c.Attribute)
291		if !present {
292			return false
293		}
294		switch c.Op {
295		case "eq":
296			return v == c.strVal
297		case "in":
298			for _, candidate := range c.inVal {
299				if v == candidate {
300					return true
301				}
302			}
303			return false
304		default:
305			// 解析阶段已拒绝未知运算符，防御性处理。
306			return false
307		}
308	}
309	
310	// MarshalResult renders the result as a single compact JSON object.
311	func MarshalResult(r EvalResult) ([]byte, error) {
312		var buf bytes.Buffer
313		enc := json.NewEncoder(&buf)
314		enc.SetEscapeHTML(false)
315		if err := enc.Encode(r); err != nil {
316			return nil, err
317		}
318		return bytes.TrimRight(buf.Bytes(), "\n"), nil
319	}
320	
321	// --- strict parsing helpers -------------------------------------------------
322	
323	// isSimpleFieldName 报告字段名是否走点号连接：以 ASCII 字母或下划线开头，
324	// 其后只能含 ASCII 字母、数字、下划线。其他任何名字（含点号、方括号、空白、
325	// 空名、非 ASCII 字符）都改用方括号包住的 JSON 字符串定位，如
326	// context["user.name"]、context[""]。
327	func isSimpleFieldName(name string) bool {
328		if name == "" {
329			return false
330		}
331		for i := 0; i < len(name); i++ {
332			c := name[i]
333			// 非 ASCII 字节（UTF-8 续字节或首字节）一律不满足“仅 ASCII”的要求。
334			if c >= 0x80 {
335				return false
336			}
337			ok := ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z') || c == '_'
338			if i > 0 {
339				ok = ok || ('0' <= c && c <= '9')
340			}
341			if !ok {
342				return false
343			}
344		}
345		return true
346	}
347	
348	// appendFieldPath 在父位置后接上一个字段：简单字段名用点号连接，其余字段名
349	// 用方括号包住一个 JSON 字符串，引号、反斜杠与控制字符按 JSON 转义显示
350	// （Marshal 对 U+2028/U+2029 也会转义，但普通可见 Unicode 保持原样）。
351	// 名字按 JSON 解码后的文字传入，因此直接字符与合法 \uXXXX 转义得到同一位置。
352	func appendFieldPath(parent, name string) string {
353		if isSimpleFieldName(name) {
354			return parent + "." + name
355		}
356		return parent + "[" + jsonQuote(name) + "]"
357	}
358	
359	// jsonQuote 把字符串渲染为带双引号的 JSON 字符串字面量：引号、反斜杠与控制
360	// 字符按 JSON 转义（U+2028/U+2029 也会转义，避免定位文字被行分隔符拆行），
361	// 其余可见字符（含 <>& 与非 ASCII 文字）保持原样。
362	func jsonQuote(s string) string {
363		var buf bytes.Buffer
364		enc := json.NewEncoder(&buf)
365		enc.SetEscapeHTML(false)
366		if err := enc.Encode(s); err != nil {
367			// 不会发生：string 的 JSON 编码没有失败路径；保留一个确定的退路。
368			return strconv.Quote(s)
369		}
370		return string(bytes.TrimRight(buf.Bytes(), "\n"))
371	}
372	
373	// jsonFrame 是 JSON 原文遍历中一个对象或数组的层级状态。重复字段检查与非法
374	// Unicode 转义检查共用这一份层级与位置定义，调整错误定位时只需改这一处。
375	type jsonFrame struct {
376		path   string // 容器自身的完整位置，如 config.flags[0].rules[1]
377		object bool
378		// keys 记录本对象已声明的字段名（按解码后的字符串），仅重复字段检查使用；
379		// Unicode 遍历不登记字段，保持 nil。
380		keys map[string]struct{}
381		// lastKey 是对象最近一个字段名，用于拼出字段值的位置。
382		lastKey string
383		// expectKey 标记对象内下一个字符串是否为字段名。
384		expectKey bool
385		// nextIndex 是数组下一个元素的下标。
386		nextIndex int
387	}
388	
389	// jsonPathTracker 是两类 JSON 检查共用的对象层级、数组位置与字段路径状态机。
390	// label 是根容器的位置前缀（"config" 或 "context"）。
391	type jsonPathTracker struct {
392		label string
393		stack []*jsonFrame
394	}
395	
396	func newJSONPathTracker(label string) *jsonPathTracker {
397		return &jsonPathTracker{label: label}
398	}
399	
400	func (t *jsonPathTracker) top() *jsonFrame {
401		return t.stack[len(t.stack)-1]
402	}
403	
404	// childPath 拼出栈顶容器内下一个子值的位置：对象的字段值按 appendFieldPath
405	// 规则连接（简单名用点号，其余用方括号 JSON 字符串），数组元素用 [下标]。
406	func (t *jsonPathTracker) childPath() string {
407		top := t.top()
408		if top.object {
409			return appendFieldPath(top.path, top.lastKey)
410		}
411		return top.path + "[" + strconv.Itoa(top.nextIndex) + "]"
412	}
413	
414	// beginContainer 在遇到 '{' 或 '[' 时压入新容器，返回新容器的完整位置。
415	func (t *jsonPathTracker) beginContainer(object bool) string {
416		path := t.label
417		if len(t.stack) > 0 {
418			path = t.childPath()
419		}
420		t.stack = append(t.stack, &jsonFrame{path: path, object: object, expectKey: object})
421		return path
422	}
423	
424	// endContainer 在遇到 '}' 或 ']' 时弹出容器，并把整个容器计为父容器中
425	// 一个已完成的值。
426	func (t *jsonPathTracker) endContainer() {
427		if len(t.stack) > 0 {
428			t.stack = t.stack[:len(t.stack)-1]
429		}
430		t.endValue()
431	}
432	
433	// atKey 报告下一个字符串是否应按对象字段名处理。
434	func (t *jsonPathTracker) atKey() bool {
435		return len(t.stack) > 0 && t.top().object && t.top().expectKey
436	}
437	
438	// currentPath 返回当前容器自身的位置（字段名报错时指向所属对象）；
439	// 栈为空时返回根标签。
440	func (t *jsonPathTracker) currentPath() string {
441		if len(t.stack) == 0 {
442			return t.label
443		}
444		return t.top().path
445	}
446	
447	// valuePath 拼出下一个字符串值（字段值或数组元素）的位置，但不改变状态。
448	func (t *jsonPathTracker) valuePath() string {
449		if len(t.stack) == 0 {
450			return t.label
451		}
452		return t.childPath()
453	}
454	
455	// endValue 在一个字段值或数组元素完成后调用：对象回到等待字段名的状态，
456	// 数组推进元素下标。
457	func (t *jsonPathTracker) endValue() {
458		if len(t.stack) == 0 {
459			return
460		}
461		top := t.top()
462		if top.object {
463			top.expectKey = true
464		} else {
465			top.nextIndex++
466		}
467	}
468	
469	// noteKey 登记一个已解码的对象字段名：更新字段路径状态，并在同一对象内第二次
470	// 声明同名字段时返回重复字段错误。
471	func (t *jsonPathTracker) noteKey(name string) error {
472		top := t.top()
473		if top.keys == nil {
474			top.keys = make(map[string]struct{})
475		}
476		if _, dup := top.keys[name]; dup {
477			return fmt.Errorf("%s: duplicate field %s", appendFieldPath(top.path, name), jsonQuote(name))
478		}
479		top.keys[name] = struct{}{}
480		top.lastKey = name
481		top.expectKey = false
482		return nil
483	}
484	
485	// setKey 在不做重复检查的遍历（Unicode 扫描）中记录一个成功解码的字段名，
486	// 仅维护字段值路径所需的状态。
487	func (t *jsonPathTracker) setKey(name string) {
488		top := t.top()
489		top.lastKey = name
490		top.expectKey = false
491	}
492	
493	// noteInvalidKey 在字段名无法解码（属于 JSON 语法错误）时仅推进键值状态：
494	// 不覆盖已记录的字段名；语法错误留给后续严格 JSON 解码报告。
495	func (t *jsonPathTracker) noteInvalidKey() {
496		t.top().expectKey = false
497	}
498	
499	// rejectDuplicateFields 按文件原文顺序扫描 JSON 令牌流，拒绝任何在同一对象内
500	// 重复声明的字段名。字段名按解码后的字符串比较（"enabled" 与 "énabled"
501	// 同名），大小写不同仍是不同字段，名字中的空白不裁剪。检查覆盖所有对象，
502	// 包括附加字段里嵌套的对象；数组元素不属于这一检查。label 是根对象的位置
503	// 前缀（"config" 或 "context"）。对象层级、数组下标与字段路径由
504	// jsonPathTracker 统一维护。JSON 语法错误不在此报告（令牌流失效即停止），
505	// 留给严格 JSON 解码。
506	func rejectDuplicateFields(raw []byte, label string) error {
507		dec := json.NewDecoder(bytes.NewReader(raw))
508		// UseNumber：数字以 json.Number 令牌返回而不转 float64，否则超出浮点范围
509		// 的合法数字（如 1e400）会让令牌流提前报错并中止，遮住其后的重复字段。
510		dec.UseNumber()
511		tracker := newJSONPathTracker(label)
512		for {
513			tok, err := dec.Token()
514			if err != nil {
515				// io.EOF 或语法错误；语法错误由后续严格 JSON 解码报告。
516				break
517			}
518			switch t := tok.(type) {
519			case json.Delim:
520				switch t {
521				case '{':
522					tracker.beginContainer(true)
523				case '[':
524					tracker.beginContainer(false)
525				case '}', ']':
526					tracker.endContainer()
527				}
528			case string:
529				if tracker.atKey() {
530					if err := tracker.noteKey(t); err != nil {
531						return err
532					}
533				} else {
534					tracker.endValue()
535				}
536			default:
537				tracker.endValue()
538			}
539		}
540		return nil
541	}
542	
543	// rejectInvalidUnicodeEscapes 按文件原文顺序扫描 JSON 文本，拒绝任何不能组成
544	// 完整字符的 \uXXXX 转义：孤立的高代理项、孤立的低代理项，以及不完整或顺序
545	// 错误的代理项对。encoding/json 解码时会把这类转义静默替换为 U+FFFD，使非法
546	// 输入与真正的 "�" 被当作相同字符串参与求值，或让字段名在替换后被误判为重复，
547	// 因此必须在解码前按原文拒绝。检查覆盖字段名与所有字符串值（包括规则的比较值、
548	// in 列表元素以及附加字段里的字符串），一个文件有多个问题时报告原文中最先出现
549	// 的一处。label 是根对象的位置前缀（"config" 或 "context"）。对象层级、数组
550	// 下标与字段路径由 jsonPathTracker 统一维护；JSON 语法错误不在此报告，留给
551	// Unmarshal。
552	func rejectInvalidUnicodeEscapes(raw []byte, label string) error {
553		tracker := newJSONPathTracker(label)
554		i := 0
555		for i < len(raw) {
556			c := raw[i]
557			switch {
558			case c == '{' || c == '[':
559				tracker.beginContainer(c == '{')
560				i++
561			case c == '}' || c == ']':
562				tracker.endContainer()
563				i++
564			case c == '"':
565				end := jsonStringEnd(raw, i)
566				contentEnd := end
567				if contentEnd > i+1 && raw[contentEnd-1] == '"' {
568					contentEnd-- // 去掉右引号；未终止的字符串留给严格 JSON 解码报告
569				}
570				content := raw[i+1 : contentEnd]
571				if tracker.atKey() {
572					if bad := findBadUnicodeEscape(content); bad != nil {
573						return fmt.Errorf("%s: field name %q contains invalid Unicode escape %s: Unicode escape does not form a complete character (%s)",
574							tracker.currentPath(), string(content), bad.escape, bad.detail)
575					}
576					// 转义已校验合法，解码用于定位路径；失败说明是语法错误，留给严格 JSON 解码。
577					if name, ok := decodeJSONString(raw[i:end]); ok {
578						tracker.setKey(name)
579					} else {
580						tracker.noteInvalidKey()
581					}
582				} else {
583					path := tracker.valuePath()
584					if bad := findBadUnicodeEscape(content); bad != nil {
585						return fmt.Errorf("%s: invalid Unicode escape %s: Unicode escape does not form a complete character (%s)",
586							path, bad.escape, bad.detail)
587					}
588					tracker.endValue()
589				}
590				i = end
591			case c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == ':' || c == ',':
592				i++
593			default:
594				// 数字与 true/false/null 等标量：跳过至下一个结构字符，按一个值计。
595				for i < len(raw) && !isJSONStructural(raw[i]) {
596					i++
597				}
598				tracker.endValue()
599			}
600		}
601		return nil
602	}
603	
604	// decodeJSONString 解码一个完整的 JSON 字符串字面量（含两侧引号）；ok 为 false
605	// 表示字面量本身非法（未终止或转义写法错误等），属于 JSON 语法错误。
606	func decodeJSONString(lit []byte) (s string, ok bool) {
607		if err := json.Unmarshal(lit, &s); err != nil {
608			return "", false
609		}
610		return s, true
611	}
612	
613	// badEscape 描述一处不能组成完整字符的 \uXXXX 转义。
614	type badEscape struct {
615		escape string // 原文中的转义序列，如 \uD800
616		detail string // 具体问题（孤立高代理项/孤立低代理项）
617	}
618	
619	// jsonStringEnd 返回从 raw[i]（必须是 '"'）开始的字符串字面量结束位置
620	// （右引号之后的下标）；未终止时返回 len(raw)。
621	func jsonStringEnd(raw []byte, i int) int {
622		j := i + 1
623		for j < len(raw) {
624			switch raw[j] {
625			case '\\':
626				j += 2
627			case '"':
628				return j + 1
629			default:
630				j++
631			}
632		}
633		return len(raw)
634	}
635	
636	// findBadUnicodeEscape 在字符串内容（不含引号）中查找第一处不能组成完整
637	// 字符的 \uXXXX 转义；没有则返回 nil。反斜杠本身的转义（\\）先于 \u 判定，
638	// 因此 "\\uD800" 只是普通文本。非法的 \u 写法（非 4 位十六进制）属于 JSON
639	// 语法错误，不在此报告。
640	func findBadUnicodeEscape(content []byte) *badEscape {
641		j := 0
642		for j < len(content) {
643			if content[j] != '\\' {
644				j++
645				continue
646			}
647			if j+1 >= len(content) {
648				break
649			}
650			if content[j+1] != 'u' {
651				j += 2
652				continue
653			}
654			if j+6 > len(content) || !isHex4(content[j+2:j+6]) {
655				j += 2
656				continue
657			}
658			cp := hexVal4(content[j+2 : j+6])
659			switch {
660			case cp >= 0xD800 && cp <= 0xDBFF:
661				// 高代理项只有紧跟一个低代理项转义才组成完整字符。
662				if j+12 <= len(content) && content[j+6] == '\\' && content[j+7] == 'u' &&
663					isHex4(content[j+8:j+12]) {
664					if lo := hexVal4(content[j+8 : j+12]); lo >= 0xDC00 && lo <= 0xDFFF {
665						j += 12
666						continue
667					}
668				}
669				return &badEscape{
670					escape: string(content[j : j+6]),
671					detail: "high surrogate is not followed by a low surrogate",
672				}
673			case cp >= 0xDC00 && cp <= 0xDFFF:
674				return &badEscape{
675					escape: string(content[j : j+6]),
676					detail: "low surrogate is not preceded by a high surrogate",
677				}
678			}
679			j += 6
680		}
681		return nil
682	}
683	
684	// isJSONStructural 报告 b 是否为 JSON 结构字符或空白（标量值的边界）。
685	func isJSONStructural(b byte) bool {
686		switch b {
687		case ' ', '\t', '\n', '\r', '{', '}', '[', ']', ':', ',', '"':
688			return true
689		}
690		return false
691	}
692	
693	// isHex4 报告 b 是否恰好为 4 个十六进制数字。
694	func isHex4(b []byte) bool {
695		if len(b) != 4 {
696			return false
697		}
698		for _, c := range b {
699			if !isHexDigit(c) {
700				return false
701			}
702		}
703		return true
704	}
705	
706	func isHexDigit(c byte) bool {
707		return ('0' <= c && c <= '9') || ('a' <= c && c <= 'f') || ('A' <= c && c <= 'F')
708	}
709	
710	// hexVal4 把 4 个十六进制数字解析为码点值；调用前须先经 isHex4 校验。
711	func hexVal4(b []byte) int {
712		v := 0
713		for _, c := range b {
714			v <<= 4
715			switch {
716			case '0' <= c && c <= '9':
717				v |= int(c - '0')
718			case 'a' <= c && c <= 'f':
719				v |= int(c-'a') + 10
720			default: // 'A' <= c && c <= 'F'
721				v |= int(c-'A') + 10
722			}
723		}
724		return v
725	}
726	
727	func parseFlag(raw any, index int) (Flag, error) {
728		loc := fmt.Sprintf("config.flags[%d]", index)
729		obj, ok := raw.(map[string]any)
730		if !ok {
731			return Flag{}, fmt.Errorf("%s: flag must be a JSON object", loc)
732		}
733		key, err := requireNonEmptyString(obj, "key", loc)
734		if err != nil {
735			return Flag{}, err
736		}
737		enabled, err := requireBool(obj, "enabled", loc)
738		if err != nil {
739			return Flag{}, err
740		}
741		def, err := requireBool(obj, "default", loc)
742		if err != nil {
743			return Flag{}, err
744		}
745		rulesArr, err := requireArrayField(obj, "rules", loc)
746		if err != nil {
747			return Flag{}, err
748		}
749		flag := Flag{Key: key, Enabled: enabled, Default: def}
750		seenRules := map[string]int{}
751		for ri, rv := range rulesArr {
752			rule, err := parseRule(rv, index, ri)
753			if err != nil {
754				return Flag{}, err
755			}
756			if prev, dup := seenRules[rule.ID]; dup {
757				return Flag{}, fmt.Errorf("%s.rules[%d].id: duplicate rule id %q (first at rules[%d])", loc, ri, rule.ID, prev)
758			}
759			seenRules[rule.ID] = ri
760			flag.Rules = append(flag.Rules, rule)
761		}
762		return flag, nil
763	}
764	
765	func parseRule(raw any, flagIndex, ruleIndex int) (Rule, error) {
766		loc := fmt.Sprintf("config.flags[%d].rules[%d]", flagIndex, ruleIndex)
767		obj, ok := raw.(map[string]any)
768		if !ok {
769			return Rule{}, fmt.Errorf("%s: rule must be a JSON object", loc)
770		}
771		id, err := requireNonEmptyString(obj, "id", loc)
772		if err != nil {
773			return Rule{}, err
774		}
775		value, err := requireBool(obj, "value", loc)
776		if err != nil {
777			return Rule{}, err
778		}
779		condsArr, err := requireArrayField(obj, "conditions", loc)
780		if err != nil {
781			return Rule{}, err
782		}
783		if len(condsArr) == 0 {
784			return Rule{}, fmt.Errorf("%s.conditions: must contain at least one condition", loc)
785		}
786		rule := Rule{ID: id, Value: value}
787		for ci, cv := range condsArr {
788			cond, err := parseCondition(cv, flagIndex, ruleIndex, ci)
789			if err != nil {
790				return Rule{}, err
791			}
792			rule.Conditions = append(rule.Conditions, cond)
793		}
794		return rule, nil
795	}
796	
797	func parseCondition(raw any, flagIndex, ruleIndex, condIndex int) (Condition, error) {
798		loc := fmt.Sprintf("config.flags[%d].rules[%d].conditions[%d]", flagIndex, ruleIndex, condIndex)
799		obj, ok := raw.(map[string]any)
800		if !ok {
801			return Condition{}, fmt.Errorf("%s: condition must be a JSON object", loc)
802		}
803		attribute, err := requireNonEmptyString(obj, "attribute", loc)
804		if err != nil {
805			return Condition{}, err
806		}
807		op, err := requireNonEmptyString(obj, "op", loc)
808		if err != nil {
809			return Condition{}, err
810		}
811		valueField, err := requireField(obj, "value", loc)
812		if err != nil {
813			return Condition{}, err
814		}
815		cond := Condition{Attribute: attribute, Op: op}
816		switch op {
817		case "eq":
818			s, ok := valueField.(string)
819			if !ok {
820				return Condition{}, fmt.Errorf("%s.value: must be a string when op is %q", loc, op)
821			}
822			cond.strVal = s
823		case "in":
824			arr, ok := valueField.([]any)
825			if !ok {
826				return Condition{}, fmt.Errorf("%s.value: must be an array when op is %q", loc, op)
827			}
828			if len(arr) == 0 {
829				return Condition{}, fmt.Errorf("%s.value: in-list must contain at least one item", loc)
830			}
831			for ii, item := range arr {
832				s, ok := item.(string)
833				if !ok {
834					return Condition{}, fmt.Errorf("%s.value[%d]: must be a string", loc, ii)
835				}
836				cond.inVal = append(cond.inVal, s)
837			}
838		default:
839			return Condition{}, fmt.Errorf("%s.op: unknown operator %q (allowed: eq, in)", loc, op)
840		}
841		return cond, nil
842	}
843	
844	func requireField(obj map[string]any, name, loc string) (any, error) {
845		v, ok := obj[name]
846		if !ok {
847			return nil, fmt.Errorf("%s: field is required", appendFieldPath(loc, name))
848		}
849		if v == nil {
850			return nil, fmt.Errorf("%s: must not be null", appendFieldPath(loc, name))
851		}
852		return v, nil
853	}
854	
855	func requireArrayField(obj map[string]any, name, loc string) ([]any, error) {
856		v, err := requireField(obj, name, loc)
857		if err != nil {
858			return nil, err
859		}
860		arr, ok := v.([]any)
861		if !ok {
862			return nil, fmt.Errorf("%s: must be an array", appendFieldPath(loc, name))
863		}
864		return arr, nil
865	}
866	
867	func requireNonEmptyString(obj map[string]any, name, loc string) (string, error) {
868		v, err := requireField(obj, name, loc)
869		if err != nil {
870			return "", err
871		}
872		s, ok := v.(string)
873		if !ok {
874			return "", fmt.Errorf("%s: must be a string", appendFieldPath(loc, name))
875		}
876		if s == "" {
877			return "", fmt.Errorf("%s: must not be empty", appendFieldPath(loc, name))
878		}
879		return s, nil
880	}
881	
882	func requireBool(obj map[string]any, name, loc string) (bool, error) {
883		v, err := requireField(obj, name, loc)
884		if err != nil {
885			return false, err
886		}
887		b, ok := v.(bool)
888		if !ok {
889			return false, fmt.Errorf("%s: must be a boolean", appendFieldPath(loc, name))
890		}
891		return b, nil
892	}
