func TestValidUnicodeEscapesUnchanged(t *testing.T) {
	// 正确配对的代理项转义与直接写出的同一字符按同一字符串比较。
	// emojiEsc 是 "😀" 的代理项对转义形式（分两段书写仅为避免源码层面的转义歧义）。
