601			t.Fatalf("demo output changed unexpectedly:\n%s", out)
602		}
603	
604		// 无参数仍运行 demo。
605		stdout.Reset()
606		if code := run(nil, &stdout, &stderr); code != 0 || !strings.Contains(stdout.String(), "intent=pay-1") {
607			t.Fatalf("no-arg demo: code=%d out=%q", code, stdout.String())
608		}
609	
610		// help 提到 evaluate 与文件格式。
611		stdout.Reset()
612		if code := run([]string{"help"}, &stdout, &stderr); code != 0 {
613			t.Fatalf("help: %d", code)
614		}
615		h := stdout.String()
616		for _, frag := range []string{"evaluate", "config.json", "context.json", "disabled|rule|default", "eq", "in"} {
617			if !strings.Contains(h, frag) {
618				t.Errorf("help missing %q", frag)
619			}
620		}
621	
622		// 未知命令仍是退出码 2。
623		stdout.Reset()
624		stderr.Reset()
625		if code := run([]string{"bogus"}, &stdout, &stderr); code != 2 {
626			t.Fatalf("unknown command exit=%d want 2", code)
627		}
628	}
629	
630	// extraCLIConfig 与 validConfig 的开关定义相同，另在顶层、开关、规则、条件上
631	// 附带对象、数组、布尔、null 与语法合法但超出浮点范围的大数字（1e400、
632	// 1 后接 400 个 0 的整数）。这些附加信息不参与求值。
633	var extraCLIConfig = `{"meta":{"owner":"pay","big":1e400,"huge":` + "1" + strings.Repeat("0", 400) + `,"tags":["x",1e400],"ok":true,"nil":null},"flags":[
634		{"key":"feature-a","enabled":true,"default":false,"note":"A","labels":["a"],"reviewed":true,"archived":null,"rules":[
635			{"id":"r-pro","value":true,"comment":{"n":1e400},"conditions":[
636				{"attribute":"plan","op":"eq","value":"pro","hint":"plan"},
637				{"attribute":"region","op":"in","value":["cn","us"],"weight":1e400}]}]},
638		{"key":"feature-b","enabled":false,"default":true,"rules":[],"meta":{"big":1e400}},
639		{"key":"feature-c","enabled":true,"default":true,"rules":[]}]}`
640	
641	func TestCLIEvaluateExtraFieldsDoNotChangeResult(t *testing.T) {
642		// 附加信息不改变求值：带附加字段的配置与 validConfig 对同一开关键、同一
643		// 上下文的输出逐字节一致；stdout 仍是单个结果对象，stderr 为空。
644		cases := []struct {
645			name string
646			key  string
647			ctx  string
648		}{
649			{"first matching rule", "feature-a", `{"plan":"pro","region":"cn"}`},
650			{"default fallback", "feature-a", `{}`},
651			{"disabled flag", "feature-b", `{"plan":"pro","region":"cn"}`},
652			{"no rules default", "feature-c", `{}`},
653		}
654		for _, tc := range cases {
655			t.Run(tc.name, func(t *testing.T) {
656				plain := newHarness(t, validConfig, tc.ctx)
657				extras := newHarness(t, extraCLIConfig, tc.ctx)
658				var plainOut, extraOut, extraErr bytes.Buffer
659				if code := run(plain.evalArgs(tc.key), &plainOut, &bytes.Buffer{}); code != 0 {
660					t.Fatalf("plain config: exit=%d", code)
661				}
662				if code := run(extras.evalArgs(tc.key), &extraOut, &extraErr); code != 0 {
663					t.Fatalf("config with extra fields: exit=%d stderr=%s", code, extraErr.String())
664				}
665				if extraErr.Len() != 0 {
666					t.Fatalf("stderr must be empty on success: %q", extraErr.String())
667				}
668				if extraOut.String() != plainOut.String() {
669					t.Fatalf("extra fields changed output: %q != %q", extraOut.String(), plainOut.String())
670				}
671				var got map[string]any
672				if err := json.Unmarshal(extraOut.Bytes(), &got); err != nil {
673					t.Fatalf("stdout is not a single JSON object: %q (%v)", extraOut.String(), err)
674				}
675				if got["key"] != tc.key {
676					t.Fatalf("unexpected payload: %v", got)
677				}
678			})
679		}
680	}
681	
682	func TestCLIEvaluateExtraFieldFailures(t *testing.T) {
683		// 附加信息虽不参与求值，仍属于被完整检查的配置：其中的重复字段与无效
684		// JSON 都要非零退出、stdout 为空，stderr 指出问题来自配置，且原因能区分
685		// 重复字段与无效 JSON。
686		hugeInt := "1" + strings.Repeat("0", 400)
687		cases := []struct {
688			name    string
689			config  string
690			key     string
691			wantSub []string // stderr 必须包含的片段
692			notSub  []string // stderr 不得包含的片段
693		}{
694			{
695				"duplicate after exponent overflow in extra object",
696				`{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],
697					"meta":{"n":1e400,"n":2}}]}`,
698				"f",
699				[]string{"config", "duplicate field", `config.flags[0].meta.n`},
700				[]string{"invalid JSON"},
701			},
702			{
703				"duplicate after 400-digit integer in extra object",
704				`{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],
705					"meta":{"n":` + hugeInt + `,"n":2}}]}`,
706				"f",
707				[]string{"config", "duplicate field", `config.flags[0].meta.n`},
708				[]string{"invalid JSON"},
709			},
710			{
711				"duplicate in unselected flag extra field",
712				`{"flags":[
713					{"key":"good","enabled":true,"default":false,"rules":[]},
714					{"key":"bad","enabled":true,"default":false,"rules":[],"meta":{"x":1,"x":2}}]}`,
715				"good",
716				[]string{"config", "duplicate field", `config.flags[1].meta.x`},
717				nil,
718			},
719			{
720				"duplicate in disabled flag extra field",
721				`{"flags":[{"key":"off","enabled":false,"default":false,"rules":[],"meta":{"x":1,"x":2}}]}`,
722				"off",
723				[]string{"config", "duplicate field", `config.flags[0].meta.x`},
724				nil,
725			},
726			{
727				"malformed number in extra field",
728				`{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],
729					"meta":{"n":1e+}}]}`,
730				"f",
731				[]string{"config: invalid JSON"},
732				[]string{"duplicate field"},
733			},
734		}
735		for _, tc := range cases {
736			t.Run(tc.name, func(t *testing.T) {
737				h := newHarness(t, tc.config, `{}`)
738				var stdout, stderr bytes.Buffer
739				if code := run(h.evalArgs(tc.key), &stdout, &stderr); code == 0 {
740					t.Fatalf("expected non-zero exit, stdout=%q", stdout.String())
741				}
742				if stdout.Len() != 0 {
743					t.Fatalf("stdout must be empty on error, got %q", stdout.String())
744				}
